    59  vcardstructuredtype *vcardstructured_new_from_string(const char *str)
    60  {
    61      struct vcardstructuredtype_impl *st = vcardstructured_alloc();
    62      if (!st) {
    63          return st;
    64      }
    65      vcardstructured_ref(st);
    66
    67      vcardstrarray *field = vcardstrarray_new(2);
    68      st->field[st->num_fields++] = field;
    69
    70      do {
    71          char *dequoted_str = vcardvalue_strdup_and_dequote_text(&str, ",;");
    72
    73          if (*str == ',' || field->num_elements || strlen(dequoted_str)) {
    74              vcardstrarray_append(field, dequoted_str);
    75          }
    76          icalmemory_free_buffer(dequoted_str);
    77
    78          if (*str == ';') {
    79              /* end of field */
    80              field = vcardstrarray_new(2);
    81              st->field[st->num_fields++] = field;
    82          }
    83
    84      } while (*str++ != '\0');
    85
    86      return st;
    87  }
